package mevwatch

import (
	"bufio"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"syscall"
)

// Block is one validated, deduplicated input block. Swaps are kept in
// canonical order: exact duplicates removed, sorted by Index.
type Block struct {
	ChainID     string
	BlockHash   string
	BlockNumber int64
	Swaps       []Swap
}

// ReportFinding is one risk conclusion inside a block report. Evidence
// carries the raw fields of every swap that participated in the judgment.
type ReportFinding struct {
	Kind     string `json:"kind"`
	Severity int    `json:"severity"`
	TxHash   string `json:"txHash"`
	Evidence []Swap `json:"evidence"`
}

// Report is the archived per-block risk report. Version records the full
// rule parameters that produced the findings, so the report stays
// interpretable without the original rule definition.
type Report struct {
	ChainID     string          `json:"chainId"`
	BlockHash   string          `json:"blockHash"`
	BlockNumber int64           `json:"blockNumber"`
	SwapCount   int             `json:"swapCount"`
	Version     RuleVersion     `json:"version"`
	Findings    []ReportFinding `json:"findings"`
}

// LineError pins a replay failure to a 1-based input line.
type LineError struct {
	Line int
	Err  error
}

func (e *LineError) Error() string { return fmt.Sprintf("line %d: %v", e.Line, e.Err) }
func (e *LineError) Unwrap() error { return e.Err }

// ErrBusy reports an archive locked by another process.
var ErrBusy = errors.New("archive is busy")

// ErrUnknownBlock reports a query for a block that was never archived.
var ErrUnknownBlock = errors.New("unknown block")

type blockID struct {
	chainID   string
	blockHash string
}

// swapLine mirrors one swap record inside a block line. Pointers
// distinguish a missing field (or an explicit null) from an explicit
// zero value: a replay record must be complete on its own, so In, Out,
// GasPrice and Index are all required and may not be null.
type swapLine struct {
	TxHash   *string `json:"TxHash"`
	Pool     *string `json:"Pool"`
	Trader   *string `json:"Trader"`
	In       *int64  `json:"In"`
	Out      *int64  `json:"Out"`
	GasPrice *int64  `json:"GasPrice"`
	Index    *int    `json:"Index"`
}

// blockLine mirrors one input line. Pointers distinguish a missing field
// from an explicit zero value.
type blockLine struct {
	ChainID     *string     `json:"chainId"`
	BlockHash   *string     `json:"blockHash"`
	BlockNumber *int64      `json:"blockNumber"`
	Swaps       *[]swapLine `json:"swaps"`
}

func parseBlock(text string) (Block, error) {
	var raw blockLine
	dec := json.NewDecoder(strings.NewReader(text))
	if err := dec.Decode(&raw); err != nil {
		return Block{}, fmt.Errorf("invalid JSON: %w", err)
	}
	if err := blockTrailingData(text, int(dec.InputOffset())); err != nil {
		return Block{}, err
	}
	if raw.ChainID == nil || *raw.ChainID == "" {
		return Block{}, errors.New("chainId must be a non-empty string")
	}
	if raw.BlockHash == nil || *raw.BlockHash == "" {
		return Block{}, errors.New("blockHash must be a non-empty string")
	}
	if raw.BlockNumber == nil {
		return Block{}, errors.New("blockNumber is required")
	}
	if *raw.BlockNumber < 0 {
		return Block{}, fmt.Errorf("blockNumber must be non-negative, got %d", *raw.BlockNumber)
	}
	if raw.Swaps == nil {
		return Block{}, errors.New("swaps must be an array")
	}

	byTx := make(map[string]Swap)
	byIndex := make(map[int]string)
	swaps := []Swap{}
	for i, s := range *raw.Swaps {
		if s.TxHash == nil || *s.TxHash == "" {
			return Block{}, fmt.Errorf("swaps[%d]: TxHash must not be empty", i)
		}
		if s.Pool == nil || *s.Pool == "" {
			return Block{}, fmt.Errorf("swaps[%d]: Pool must not be empty", i)
		}
		if s.Trader == nil || *s.Trader == "" {
			return Block{}, fmt.Errorf("swaps[%d]: Trader must not be empty", i)
		}
		// Every numeric field must be present and non-null in this very
		// record; an explicit zero is a valid value, never a missing one.
		// Values must not be borrowed from a neighbour, a same-hash record
		// or a default, so an incomplete record is rejected before dedup
		// even when a complete record with the same tx hash exists.
		for _, f := range []struct {
			name string
			v    *int64
		}{
			{"In", s.In}, {"Out", s.Out}, {"GasPrice", s.GasPrice},
		} {
			if f.v == nil {
				return Block{}, fmt.Errorf("swaps[%d]: %s is required and must not be null", i, f.name)
			}
		}
		if s.Index == nil {
			return Block{}, fmt.Errorf("swaps[%d]: Index is required and must not be null", i)
		}
		in, out, gasPrice, index := *s.In, *s.Out, *s.GasPrice, *s.Index
		if in < 0 || out < 0 || gasPrice < 0 || index < 0 {
			return Block{}, fmt.Errorf("swaps[%d]: In, Out, GasPrice and Index must be non-negative", i)
		}
		swap := Swap{
			TxHash: *s.TxHash, Pool: *s.Pool, Trader: *s.Trader,
			In: in, Out: out, GasPrice: gasPrice, Index: index,
		}
		if prev, ok := byTx[swap.TxHash]; ok {
			if prev != swap {
				return Block{}, fmt.Errorf("swaps[%d]: conflicting records for tx %s", i, swap.TxHash)
			}
			continue // exact duplicate, keep one copy
		}
		if other, ok := byIndex[swap.Index]; ok {
			return Block{}, fmt.Errorf("swaps[%d]: Index %d already used by tx %s", i, swap.Index, other)
		}
		byTx[swap.TxHash] = swap
		byIndex[swap.Index] = swap.TxHash
		swaps = append(swaps, swap)
	}
	sort.Slice(swaps, func(i, j int) bool { return swaps[i].Index < swaps[j].Index })
	return Block{
		ChainID:     *raw.ChainID,
		BlockHash:   *raw.BlockHash,
		BlockNumber: *raw.BlockNumber,
		Swaps:       swaps,
	}, nil
}

// blockTrailingData names the first non-whitespace byte after the block
// object on a replay line, so an unmatched '}' or ']' — or a second value
// of any kind — is reported directly; only whitespace may follow the
// object. dec.More cannot see this: after a complete top-level value it
// only looks for the start of another value and treats stray closing
// brackets as "nothing more".
func blockTrailingData(text string, offset int) error {
	rest := strings.TrimLeft(text[offset:], " \t\n\r")
	if len(rest) > 0 {
		return fmt.Errorf("invalid JSON: unexpected trailing data after block object: %s", trailingTokenName(rest[0]))
	}
	return nil
}

func swapsEqual(a, b []Swap) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

// sameContent reports whether two blocks carry the same content. Both sides
// are canonical (deduplicated, sorted by Index), so ordering and exact
// duplicates in the input do not affect the comparison.
func sameContent(blockNumber int64, swaps []Swap, b Block) bool {
	return blockNumber == b.BlockNumber && swapsEqual(swaps, b.Swaps)
}

// DetectBlock checks every swap against its adjacent neighbours within its
// pool under the built-in rules. See DetectBlockWithRules.
func DetectBlock(swaps []Swap) []ReportFinding {
	return DetectBlockWithRules(swaps, BuiltinVersion().Rules)
}

// DetectBlockWithRules checks every swap against its adjacent neighbours
// within its pool under the given rule version: a sandwich when the same
// trader brackets the victim with higher gas on both sides, otherwise a
// displacement when the previous swap's gas strictly exceeds the configured
// multiple of the victim's. The last swap of a pool is checked too. An
// enabled sandwich takes priority over displacement for the same victim;
// with the sandwich rule off the victim can still be flagged for
// displacement. With both rules off the result is an empty slice. The
// judgment itself is shared with Detect; this entry only adds the block
// report's raw-swap evidence and ordering.
func DetectBlockWithRules(swaps []Swap, rules RuleSet) []ReportFinding {
	pools := make(map[string][]Swap)
	for _, s := range swaps {
		pools[s.Pool] = append(pools[s.Pool], s)
	}
	findings := []ReportFinding{}
	for _, pool := range pools {
		sort.Slice(pool, func(i, j int) bool { return pool[i].Index < pool[j].Index })
		for i, victim := range pool {
			var front, back *Swap
			if i > 0 {
				front = &pool[i-1]
			}
			if i+1 < len(pool) {
				back = &pool[i+1]
			}
			j, hit := judgeVictim(front, victim, back, rules)
			if !hit {
				continue
			}
			// The evidence keeps the full swap fields of every record that
			// participated: front, victim, and for a sandwich also back.
			evidence := []Swap{*front, victim}
			if j.kind == "sandwich" {
				evidence = append(evidence, *back)
			}
			findings = append(findings, ReportFinding{
				Kind: j.kind, Severity: j.severity, TxHash: victim.TxHash,
				Evidence: evidence,
			})
		}
	}
	sort.Slice(findings, func(i, j int) bool {
		if findings[i].Severity != findings[j].Severity {
			return findings[i].Severity > findings[j].Severity
		}
		return findings[i].TxHash < findings[j].TxHash
	})
	return findings
}

// record is the archived form of a block: the report plus the canonical
// swaps, so a later import can detect content conflicts. Version carries
// the full rule parameters used for the findings; it is nil only in
// archives written before rule versions existed, which are interpreted
// under the built-in rules.
type record struct {
	ChainID     string          `json:"chainId"`
	BlockHash   string          `json:"blockHash"`
	BlockNumber int64           `json:"blockNumber"`
	Swaps       []Swap          `json:"swaps"`
	Findings    []ReportFinding `json:"findings"`
	Version     *RuleVersion    `json:"version,omitempty"`
}

func (r record) ruleVersion() RuleVersion {
	if r.Version != nil {
		return *r.Version
	}
	return BuiltinVersion()
}

// queryRecord mirrors one archived record the way a report query reads it.
// Every business field is decoded normally, but the archived rule-version
// declaration is kept as its raw stored document. The decoded struct cannot
// tell a missing field, an explicit null or a wrong-typed value from a real
// one: decoding the embedded version into the struct would show a decayed
// report under silently zeroed parameters (enabled false, severity 0, a
// zero displacement multiplier), and — because a null or incomplete
// declaration carries no usable id — risk explaining it as the built-in
// rules. A zero-length Version means the "version" key is absent entirely
// (a value-type RawMessage is left untouched for a missing key), which
// alone is the legacy, pre-version format interpreted under the built-in
// rules; any present value — the bytes "null", {} or an object — is kept
// byte for byte and must be re-validated from those bytes before the
// report is shown.
type queryRecord struct {
	ChainID     string          `json:"chainId"`
	BlockHash   string          `json:"blockHash"`
	BlockNumber int64           `json:"blockNumber"`
	Swaps       []Swap          `json:"swaps"`
	Findings    []ReportFinding `json:"findings"`
	Version     json.RawMessage `json:"version"`
}

// archivedReportVersion proves the version declaration embedded in an
// archived record still satisfies every registration rule, re-validating
// the raw document with the same parser registrations pass. A wholly
// absent "version" key is the only legacy shape and means the built-in
// rules; anything actually saved — null, an empty object, an incomplete
// declaration, a wrong type, an out-of-range number, an unknown or
// duplicated field — is corruption rather than a zero-filled or built-in
// parameter set. An id of "builtin" names the same saved declaration and
// is validated just like any other id; it never bypasses the check.
func archivedReportVersion(raw json.RawMessage) (RuleVersion, error) {
	if len(raw) == 0 {
		return BuiltinVersion(), nil
	}
	return ParseRuleVersion(raw)
}

// corruptReportError names the chain and block a failed report query
// targets, the saved version identifier when the document still carries a
// readable one (so corruption is not mistaken for an unregistered
// version), and the offending rule or field from the validation failure.
// It wraps both ErrCorruptVersion and the underlying cause (for example
// ErrDuplicateField).
func corruptReportError(chainID, blockHash string, raw json.RawMessage, cause error) error {
	if id := identifiableVersionID(raw); id != "unidentifiable version" {
		return fmt.Errorf("%w: archived report for chain %s block %s uses version %q: %w",
			ErrCorruptVersion, chainID, blockHash, id, cause)
	}
	return fmt.Errorf("%w: archived report for chain %s block %s: %w",
		ErrCorruptVersion, chainID, blockHash, cause)
}

// reportFromQueryRecord builds the Report presented for one archived
// record, proving the complete version declaration the record archived
// before any conclusion is shown. A report query and an identical reimport
// take this same path, so a re-imported block whose content matches the
// archive is held to exactly the standard of a standalone report query:
// a wholly absent version key is the one legacy shape and means the
// built-in rules, while a declaration actually saved as null, as an empty
// object, only in part, with a wrong type or an out-of-range number, an
// unknown or repeated field — an id of "builtin" included — fails as
// ErrCorruptVersion naming the chain, the block, the readable saved id
// and the offending rule or field. The parameters are never zero-filled,
// borrowed from the enabled or a registered version, or re-detected; the
// archived findings, evidence and swap count are returned as stored.
func reportFromQueryRecord(rec *queryRecord) (Report, error) {
	version, err := archivedReportVersion(rec.Version)
	if err != nil {
		return Report{}, corruptReportError(rec.ChainID, rec.BlockHash, rec.Version, err)
	}
	return Report{
		ChainID:     rec.ChainID,
		BlockHash:   rec.BlockHash,
		BlockNumber: rec.BlockNumber,
		SwapCount:   len(rec.Swaps),
		Version:     version,
		Findings:    rec.Findings,
	}, nil
}

func (r record) report() Report {
	return Report{
		ChainID:     r.ChainID,
		BlockHash:   r.BlockHash,
		BlockNumber: r.BlockNumber,
		SwapCount:   len(r.Swaps),
		Version:     r.ruleVersion(),
		Findings:    r.Findings,
	}
}

const (
	archiveFileName = "archive.json"
	lockFileName    = "lock"
)

type archiveData struct {
	Records []record `json:"records"`
	// Versions and EnabledVersion are absent in archives written before
	// rule versions existed; such archives run the built-in rules.
	Versions       []RuleVersion `json:"versions,omitempty"`
	EnabledVersion string        `json:"enabledVersion,omitempty"`
	// Suppressions and AlertRecords are absent in archives written before
	// offline alerting existed; such archives simply have no registered
	// conditions and no processing history.
	Suppressions []Suppression      `json:"suppressions,omitempty"`
	AlertRecords []ProcessingRecord `json:"alerts,omitempty"`
	// Reviews is absent in archives written before manual reviews existed;
	// every conclusion then behaves as unreviewed.
	Reviews []ReviewObject `json:"reviews,omitempty"`
}

// readArchiveBytes returns the exact bytes of the archive file, or nil
// when no archive exists yet.
func readArchiveBytes(dir string) ([]byte, error) {
	raw, err := os.ReadFile(filepath.Join(dir, archiveFileName))
	if errors.Is(err, os.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	return raw, nil
}

func readArchive(dir string) (archiveData, error) {
	raw, err := readArchiveBytes(dir)
	if err != nil {
		return archiveData{}, err
	}
	if raw == nil {
		return archiveData{Records: []record{}}, nil
	}
	var data archiveData
	if err := json.Unmarshal(raw, &data); err != nil {
		return archiveData{}, fmt.Errorf("archive is corrupted: %w", err)
	}
	return data, nil
}

// replayArchiveDoc mirrors the archive file the way a replay reads and
// writes it: every record and every registered version is kept as its raw
// stored document, while suppressions, alert records and reviews are fully
// decoded. A corrupt document — a wrong-typed field, say — then cannot
// break the read or masquerade as whole-archive corruption; the version
// this run selects is judged on its own by intactVersion, and an already
// archived block whose content matches the input is judged on its own from
// its record's raw bytes exactly the way a report query proves it, rather
// than decoded into silently zeroed parameters or a null-explained
// built-in report. Entries the run does not touch are written back byte
// for byte: a replay never repairs, completes or drops a stored record or
// version, not even a corrupt one.
type replayArchiveDoc struct {
	Records        []json.RawMessage  `json:"records"`
	Versions       []json.RawMessage  `json:"versions,omitempty"`
	EnabledVersion string             `json:"enabledVersion,omitempty"`
	Suppressions   []Suppression      `json:"suppressions,omitempty"`
	AlertRecords   []ProcessingRecord `json:"alerts,omitempty"`
	Reviews        []ReviewObject     `json:"reviews,omitempty"`
}

// writeArchiveAtomic replaces the archive file in one rename, so a crash
// can only expose the previous or the next complete commit, never a half
// written file.
func writeArchiveAtomic(dir string, data any) error {
	raw, err := json.MarshalIndent(data, "", "  ")
	if err != nil {
		return err
	}
	tmp := filepath.Join(dir, archiveFileName+".tmp")
	f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
	if err != nil {
		return err
	}
	if _, err := f.Write(raw); err != nil {
		f.Close()
		os.Remove(tmp)
		return err
	}
	if err := f.Sync(); err != nil {
		f.Close()
		os.Remove(tmp)
		return err
	}
	if err := f.Close(); err != nil {
		os.Remove(tmp)
		return err
	}
	if err := os.Rename(tmp, filepath.Join(dir, archiveFileName)); err != nil {
		os.Remove(tmp)
		return err
	}
	if d, err := os.Open(dir); err == nil {
		d.Sync()
		d.Close()
	}
	return nil
}

// lockArchive takes an flock on the archive's lock file. The lock is
// released automatically if the process dies, so no stale locks survive.
func lockArchive(dir string, how int) (*os.File, error) {
	f, err := os.OpenFile(filepath.Join(dir, lockFileName), os.O_CREATE|os.O_RDWR, 0o644)
	if err != nil {
		return nil, err
	}
	if err := syscall.Flock(int(f.Fd()), how); err != nil {
		f.Close()
		if errors.Is(err, syscall.EWOULDBLOCK) {
			return nil, ErrBusy
		}
		return nil, err
	}
	return f, nil
}

type parsedBlock struct {
	line  int
	block Block
}

func parseBlocks(r io.Reader) ([]parsedBlock, error) {
	var out []parsedBlock
	reader := bufio.NewReader(r)
	lineNo := 0
	for {
		raw, err := reader.ReadBytes('\n')
		if len(raw) > 0 {
			lineNo++
		}
		if text := strings.TrimSpace(string(raw)); text != "" {
			block, perr := parseBlock(text)
			if perr != nil {
				return nil, &LineError{Line: lineNo, Err: perr}
			}
			out = append(out, parsedBlock{line: lineNo, block: block})
		}
		if err == io.EOF {
			return out, nil
		}
		if err != nil {
			return nil, err
		}
	}
}

// ReplayFile imports the line-delimited blocks in inputPath into the
// archive at dir and returns one report per distinct block, in order of
// first appearance. New blocks are judged under the archive's currently
// enabled rule version; that version's stored document must still satisfy
// the registration rules in full, or the whole replay fails with
// ErrCorruptVersion before any report is produced.
func ReplayFile(inputPath, dir string) ([]Report, error) {
	return replayFile(inputPath, dir, "")
}

// ReplayFileWithVersion is ReplayFile under an explicitly registered rule
// version instead of the archive's enabled one. The named version's stored
// document must still satisfy the registration rules in full; a corrupt
// one fails the whole replay with ErrCorruptVersion rather than judging
// under zeroed or substituted parameters.
func ReplayFileWithVersion(inputPath, dir, versionID string) ([]Report, error) {
	if versionID == "" {
		return nil, errors.New("version id must not be empty")
	}
	return replayFile(inputPath, dir, versionID)
}

func replayFile(inputPath, dir, versionID string) ([]Report, error) {
	f, err := os.Open(inputPath)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	return doReplay(f, dir, versionID)
}

// Replay parses, validates and archives blocks from r under the archive's
// currently enabled rule version. Every line is checked before anything is
// written; any failure leaves the archive untouched. New reports are
// committed together in a single atomic write. The selected version's
// stored document is re-validated before any block is judged: a corrupt
// version fails the whole replay with ErrCorruptVersion — never a
// substituted or zeroed parameter set — even when no input block would
// have triggered the damaged rule.
//
// A block that is already archived and arrives with identical content is
// not re-judged: its original report is returned. Before that report is
// returned the declaration the record archived is proved from its raw
// bytes by exactly the standard a standalone report query (Query)
// enforces — a non-empty id, both rules each declaring a boolean enabled
// and an integer severity 1-5, and a displacement multiplier 2-100 —
// rather than trusted because this run's own version is legal. A
// declaration saved as null, as an empty object, only in part, with a
// wrong type or out-of-range number, an unknown rule or field, or a field
// repeated in one object (the field-name folding and escapes included,
// even when both values agree) fails the whole replay with
// ErrCorruptVersion; an explicit enabled:false is a legal off state but a
// disabled rule still has to be declared completely. Only a wholly absent
// version key — the pre-version legacy shape — is explained by the
// built-in rules; a written "builtin" id is validated like every other.
// On failure no report is returned, no same-batch new block is saved and
// no archived content changes, regardless of where the corrupt old block
// sits relative to the new ones. An intact old report is returned with
// its originally saved conclusions, evidence, swap count and full
// parameters, never re-detected and never completed from the currently
// enabled or a same-id registered version; its historical id need not
// still be registered.
func Replay(input io.Reader, dir string) ([]Report, error) {
	return doReplay(input, dir, "")
}

// ReplayWithVersion is Replay under an explicitly registered rule version
// instead of the archive's enabled one, with the same integrity check: a
// corrupt stored version document fails the whole replay with
// ErrCorruptVersion before any report is produced.
func ReplayWithVersion(input io.Reader, dir, versionID string) ([]Report, error) {
	if versionID == "" {
		return nil, errors.New("version id must not be empty")
	}
	return doReplay(input, dir, versionID)
}

func doReplay(input io.Reader, dir, versionID string) ([]Report, error) {
	parsed, err := parseBlocks(input)
	if err != nil {
		return nil, err
	}

	// Collapse repeated identities within this file, keeping first
	// appearance order; conflicting content rejects the whole file.
	type occurrence struct {
		block Block
		line  int
	}
	order := []occurrence{}
	firstSeen := make(map[blockID]int)
	for _, p := range parsed {
		id := blockID{p.block.ChainID, p.block.BlockHash}
		if first, ok := firstSeen[id]; ok {
			if !sameContent(order[first].block.BlockNumber, order[first].block.Swaps, p.block) {
				return nil, &LineError{Line: p.line, Err: fmt.Errorf(
					"block %s/%s conflicts with line %d", id.chainID, id.blockHash, order[first].line)}
			}
			continue
		}
		firstSeen[id] = len(order)
		order = append(order, occurrence{block: p.block, line: p.line})
	}

	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, err
	}
	lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
	if err != nil {
		return nil, err
	}
	defer lock.Close()

	// Decode with every stored record and registered version kept as its
	// raw stored document, so a wrong-typed field in one entry is that
	// entry's corruption, not whole-archive corruption: the selected
	// version's document is re-validated from its bytes the same way a
	// single-block comparison proves its version intact, and each already
	// archived block this run re-imports is proved from its record's raw
	// bytes the same way a standalone report query proves it, rather than
	// decoded into silently zeroed parameters or a null-explained
	// built-in report.
	raw, err := readArchiveBytes(dir)
	if err != nil {
		return nil, err
	}
	data := replayArchiveDoc{Records: []json.RawMessage{}}
	if raw != nil {
		if err := json.Unmarshal(raw, &data); err != nil {
			return nil, fmt.Errorf("archive is corrupted: %w", err)
		}
	}
	// Resolve the version once, while the exclusive lock is held: every
	// new block in this run is judged under the same rules even if another
	// process enables a different version right after we finish. The
	// selected version's stored document must still satisfy the
	// registration rules in full; a corrupt one fails the whole replay
	// with ErrCorruptVersion here, before any block is judged, any report
	// is produced or anything is written — even when the input is empty,
	// holds only blocks already archived, or would never trigger the
	// damaged rule. The corrupt content is never replaced by the enabled
	// version, the built-in rules or defaults.
	version, err := resolveReplayVersion(data, versionID)
	if err != nil {
		return nil, err
	}
	// Index the stored records by block identity with their decoded
	// content; the embedded version stays raw until an identical reimport
	// actually has to present that record's report, when its saved
	// declaration is proved exactly as a report query would.
	stored := make([]queryRecord, len(data.Records))
	archived := make(map[blockID]int, len(data.Records))
	for i, rawRec := range data.Records {
		var qr queryRecord
		if err := json.Unmarshal(rawRec, &qr); err != nil {
			return nil, fmt.Errorf("archive is corrupted: record %d: %w", i, err)
		}
		stored[i] = qr
		archived[blockID{qr.ChainID, qr.BlockHash}] = i
	}

	reports := make([]Report, 0, len(order))
	newRecords := []json.RawMessage{}
	for _, occ := range order {
		id := blockID{occ.block.ChainID, occ.block.BlockHash}
		if idx, ok := archived[id]; ok {
			rec := stored[idx]
			if !sameContent(rec.BlockNumber, rec.Swaps, occ.block) {
				return nil, &LineError{Line: occ.line, Err: fmt.Errorf(
					"block %s/%s conflicts with the archived record", id.chainID, id.blockHash)}
			}
			// Identical re-import: return the original report, add nothing.
			// The saved declaration is held to the standard of a standalone
			// report query before any conclusion is returned — never read as
			// built-in from a null version or as zeroed parameters from an
			// incomplete one, and never completed from the version this run
			// selected. A corrupt declaration fails the whole batch here,
			// before a single new block is committed, whether the old block
			// appears before or after the new ones.
			report, perr := reportFromQueryRecord(&rec)
			if perr != nil {
				return nil, &LineError{Line: occ.line, Err: perr}
			}
			reports = append(reports, report)
			continue
		}
		rec := record{
			ChainID:     occ.block.ChainID,
			BlockHash:   occ.block.BlockHash,
			BlockNumber: occ.block.BlockNumber,
			Swaps:       occ.block.Swaps,
			Findings:    DetectBlockWithRules(occ.block.Swaps, version.Rules),
			Version:     &version,
		}
		rawRec, perr := json.Marshal(rec)
		if perr != nil {
			return nil, perr
		}
		newRecords = append(newRecords, rawRec)
		reports = append(reports, rec.report())
	}
	// All blocks passed — new and identical alike — so commit the new
	// records once, leaving every stored record's raw bytes untouched.
	if len(newRecords) > 0 {
		data.Records = append(data.Records, newRecords...)
		if err := writeArchiveAtomic(dir, data); err != nil {
			return nil, err
		}
	}
	return reports, nil
}

// resolveReplayVersion picks the rule version for one replay run — the
// explicitly requested one, or the archive's currently enabled version —
// and proves its stored archive document still satisfies every
// registration rule, re-validating the raw document with the same parser
// registrations pass. The decoded struct cannot do this: a missing
// enabled, severity or multiplier field unmarshals as the zero value and
// is indistinguishable from an explicitly declared one, and a zero
// displacement multiplier even crashes detection. An explicitly declared
// false or any in-range value is valid; a missing or null field, a wrong
// type or an out-of-range number makes the version corrupt, and the
// failure names the version and the offending rule or field. Archives
// written before rule versions existed have no enabled marker and run the
// built-in rules; the built-in version is constructed in code and always
// intact.
func resolveReplayVersion(data replayArchiveDoc, versionID string) (RuleVersion, error) {
	id := versionID
	if id == "" {
		id = data.EnabledVersion
		if id == "" {
			return BuiltinVersion(), nil
		}
	}
	return intactVersion(data.Versions, id)
}

// queryArchiveDoc mirrors just the records a report query reads, keeping
// each record's embedded version declaration as its raw stored document —
// the same shape registered versions are kept in everywhere else — so a
// wrong-typed field in one report's declaration fails that report's query
// rather than breaking the whole-archive decode or decoding into silently
// zeroed parameters.
type queryArchiveDoc struct {
	Records []queryRecord `json:"records"`
}

// Query returns the archived report for one block identity. It only reads
// the archive; the original input file is not needed, and neither a
// successful nor a failed query rewrites anything.
//
// Before the report is returned, the complete version declaration the
// report archived is re-validated from its raw bytes with the same proof
// registration, enable, comparison, evaluation and replay demand: a
// non-empty version identifier, both the sandwich and displacement rules
// each with a boolean enabled and an integer severity in 1-5, and the
// displacement multiplier an integer in 2-100. A missing or null field or
// rule object, a wrong type, an out-of-range number, an unknown field or
// rule, or a field declared twice in one object (an exact repeat, an
// escaped spelling or a case-only spelling that names the same field —
// even when both values agree) makes the saved declaration corrupt. An
// explicit enabled:false is a legal off state, not damage; the disabled
// rule still has to carry complete, in-range parameters.
//
// Only an old-format record with no "version" key at all keeps the
// original built-in interpretation. A declaration actually saved as null,
// as an empty object or only in part is corruption, and an id of
// "builtin" is validated like every other id rather than bypassing the
// check. On corruption Query fails with ErrCorruptVersion naming the
// target chain and block, the readable saved version id and the offending
// rule or field; it never zero-fills the parameters, explains them as
// built-in, or substitutes parameters from the currently enabled or a
// registered version. The report uses the parameters it archived and is
// never re-detected. A block that was never archived stays
// ErrUnknownBlock.
func Query(dir, chainID, blockHash string) (Report, error) {
	if _, err := os.Stat(dir); err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return Report{}, ErrUnknownBlock
		}
		return Report{}, err
	}
	lock, err := lockArchive(dir, syscall.LOCK_SH)
	if err != nil {
		return Report{}, err
	}
	defer lock.Close()

	raw, err := readArchiveBytes(dir)
	if err != nil {
		return Report{}, err
	}
	var doc queryArchiveDoc
	if len(raw) > 0 {
		if err := json.Unmarshal(raw, &doc); err != nil {
			return Report{}, fmt.Errorf("archive is corrupted: %w", err)
		}
	}
	idx := -1
	for i := range doc.Records {
		if doc.Records[i].ChainID == chainID && doc.Records[i].BlockHash == blockHash {
			idx = i
			break
		}
	}
	if idx < 0 {
		return Report{}, ErrUnknownBlock
	}
	rec := &doc.Records[idx]
	return reportFromQueryRecord(rec)
}

package mevwatch

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"sort"
	"strconv"
	"strings"
	"syscall"
)

// Offline alerting turns conclusions already stored in an archive into
// alert processing records. It never re-runs detection: a record always
// reflects the finding, the rule version and the parameters that were in
// force when the block was archived.

// Alert statuses. A finding above the generation threshold becomes an
// "alert"; a finding that matches one or more registered suppression
// conditions at its block height becomes "suppressed" instead.
const (
	AlertStatusAlert      = "alert"
	AlertStatusSuppressed = "suppressed"
)

// Suppression condition kinds.
const (
	SuppressSandwich     = "sandwich"
	SuppressDisplacement = "displacement"
)

// ErrUnknownKind reports a conclusion/condition kind that is neither
// sandwich nor displacement.
var ErrUnknownKind = errors.New("unknown kind")

// ErrSuppressionConflict reports re-registering an existing suppression ID
// with different content.
var ErrSuppressionConflict = errors.New("suppression already registered with different content")

// ErrUnknownSuppression reports revoking a condition ID that is not
// registered in the archive (including the empty archive).
var ErrUnknownSuppression = errors.New("unknown suppression condition")

// SuppressionHit records one suppression condition that matched an event.
type SuppressionHit struct {
	ID     string `json:"id"`
	Reason string `json:"reason"`
}

// ProcessingRecord is one fully resolved alerting outcome. Its identity is
// (chain, block hash, victim tx hash, conclusion kind, channel): once a
// record exists for that identity, no later import, wider or overlapping
// height range, rule-version switch or restart can produce it again. The
// record keeps the complete block identity, pool, conclusion, raw swap
// evidence, the detection version and its parameters, the threshold used at
// generation time, and every suppression condition that matched.
type ProcessingRecord struct {
	ChainID      string           `json:"chainId"`
	BlockHash    string           `json:"blockHash"`
	BlockNumber  uint64           `json:"blockNumber"`
	Pool         string           `json:"pool"`
	Channel      string           `json:"channel"`
	Finding      ReportFinding    `json:"finding"`
	Version      RuleVersion      `json:"version"`
	MinSeverity  int              `json:"minSeverity"`
	Status       string           `json:"status"`
	Suppressions []SuppressionHit `json:"suppressions"`
}

func (r ProcessingRecord) identity() alertKey {
	return alertKey{
		chainID:   r.ChainID,
		blockHash: r.BlockHash,
		txHash:    r.Finding.TxHash,
		kind:      r.Finding.Kind,
		channel:   r.Channel,
	}
}

// Suppression is one registered suppression condition. Every field matches
// exactly (the pool is matched against the pool of the victim swap's
// original exchange record), and an event at height h is covered when
// StartHeight <= h <= EndHeight.
//
// Revoked marks a condition whose user has withdrawn it. A revoked
// condition is kept for audit but never matches later processing; the
// field is always serialized (an absent value in an old archive decodes
// to false, i.e. not revoked) and cannot be set through a registration
// document. Revocation applies to findings processed afterwards only —
// event height never decides when it takes effect.
type Suppression struct {
	ID          string `json:"id"`
	ChainID     string `json:"chainId"`
	Pool        string `json:"pool"`
	Kind        string `json:"kind"`
	Channel     string `json:"channel"`
	StartHeight uint64 `json:"startHeight"`
	EndHeight   uint64 `json:"endHeight"`
	Reason      string `json:"reason"`
	Revoked     bool   `json:"revoked"`
}

// covers reports whether the suppression applies to an event on chain at
// height in the given pool/kind/channel. Matching depends only on the
// event's height, never on operation time, import order or the archive's
// highest block.
func (s Suppression) covers(chainID, pool, kind, channel string, height uint64) bool {
	return s.ChainID == chainID && s.Pool == pool && s.Kind == kind && s.Channel == channel &&
		s.StartHeight <= height && height <= s.EndHeight
}

// alertKey is the deduplication identity of a processing record.
type alertKey struct {
	chainID   string
	blockHash string
	txHash    string
	kind      string
	channel   string
}

// suppressionSpec mirrors one suppression registration document. Pointers
// distinguish missing fields from explicit zero values; heights are parsed
// separately as unsigned 64-bit integers.
type suppressionSpec struct {
	ID          *string `json:"id"`
	ChainID     *string `json:"chainId"`
	Pool        *string `json:"pool"`
	Kind        *string `json:"kind"`
	Channel     *string `json:"channel"`
	StartHeight *uint64 `json:"startHeight"`
	EndHeight   *uint64 `json:"endHeight"`
	Reason      *string `json:"reason"`
}

func nonEmpty(field string, v *string) (string, error) {
	if v == nil {
		return "", fmt.Errorf("%s is required (non-empty string)", field)
	}
	if strings.TrimSpace(*v) == "" {
		return "", fmt.Errorf("%s must be a non-empty string", field)
	}
	return *v, nil
}

// suppressionFields lists every field name a registration document may
// declare, in the struct's JSON spelling.
var suppressionFields = []string{"id", "chainId", "pool", "kind", "channel", "startHeight", "endHeight", "reason"}

// suppressionScanPolicy validates the shape of a suppression document with
// the shared scanner. Unlike the version document, a suppression document
// is flat: nested values carry no field table of their own, and only known
// fields take part in duplicate detection (an unknown key is left for the
// typed decoder to reject).
var suppressionScanPolicy = specPolicy{
	topObject:          "suppression spec",
	known:              fieldTable(suppressionFields...),
	rejectExactUnknown: false,
	firstTokenError: func(err error) error {
		return fmt.Errorf("invalid suppression spec: %w", err)
	},
	nonObject: func(json.Token) error {
		return errors.New("invalid suppression spec: expected a single JSON object")
	},
	wrap: func(err error) error {
		return fmt.Errorf("invalid suppression spec: %w", err)
	},
	duplicate: func(_ string, canonical, first, spelling string) error {
		return fmt.Errorf("invalid suppression spec: duplicate field %q (declared as %q and %q)", canonical, first, spelling)
	},
	trailing: suppressionTrailingData,
}

// validateSuppressionDocument checks the raw registration input
// structurally before any field is read: it must hold exactly one complete
// JSON object — leading and trailing whitespace is fine, but empty input,
// arrays, null, scalars and incomplete objects are not, and no byte other
// than whitespace may follow the closing brace (a second object, an extra
// } or ] or any other JSON value is rejected). Inside the object every
// known field may be declared at most once: field names are compared after
// JSON unescaping with the decoder's own field-name folding, and two
// spellings that resolve to the same field — differing only in case, like
// channel and CHANNEL, or in a compatibility character, like U+017F for
// s — count as one duplicate declaration even when both carry the same
// value.
func validateSuppressionDocument(raw []byte) error {
	return scanJSONObject(raw, suppressionScanPolicy)
}

// suppressionTrailingData mirrors decoding one more value after the
// object: the only legal remainder is whitespace, which reports io.EOF;
// a second value or an unmatched bracket yields any other error and is
// trailing data.
func suppressionTrailingData(raw []byte, offset int) error {
	dec := json.NewDecoder(bytes.NewReader(raw[offset:]))
	var extra json.RawMessage
	if err := dec.Decode(&extra); err != io.EOF {
		return errors.New("invalid suppression spec: unexpected trailing data")
	}
	return nil
}

// ParseSuppression validates one registration document. Only sandwich and
// displacement kinds exist, every text field must be non-empty, heights are
// unsigned 64-bit integers and the start height must not exceed the end
// height.
func ParseSuppression(raw []byte) (Suppression, error) {
	if err := validateSuppressionDocument(raw); err != nil {
		return Suppression{}, err
	}
	var spec suppressionSpec
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&spec); err != nil {
		return Suppression{}, fmt.Errorf("invalid suppression spec: %w", err)
	}
	id, err := nonEmpty("id", spec.ID)
	if err != nil {
		return Suppression{}, err
	}
	chainID, err := nonEmpty("chainId", spec.ChainID)
	if err != nil {
		return Suppression{}, err
	}
	pool, err := nonEmpty("pool", spec.Pool)
	if err != nil {
		return Suppression{}, err
	}
	kind, err := nonEmpty("kind", spec.Kind)
	if err != nil {
		return Suppression{}, err
	}
	if kind != SuppressSandwich && kind != SuppressDisplacement {
		return Suppression{}, fmt.Errorf("%w: %q (want sandwich or displacement)", ErrUnknownKind, kind)
	}
	channel, err := nonEmpty("channel", spec.Channel)
	if err != nil {
		return Suppression{}, err
	}
	if spec.StartHeight == nil {
		return Suppression{}, errors.New("startHeight is required (unsigned 64-bit integer)")
	}
	if spec.EndHeight == nil {
		return Suppression{}, errors.New("endHeight is required (unsigned 64-bit integer)")
	}
	if *spec.StartHeight > *spec.EndHeight {
		return Suppression{}, fmt.Errorf("startHeight %d must not exceed endHeight %d", *spec.StartHeight, *spec.EndHeight)
	}
	reason, err := nonEmpty("reason", spec.Reason)
	if err != nil {
		return Suppression{}, err
	}
	return Suppression{
		ID:          id,
		ChainID:     chainID,
		Pool:        pool,
		Kind:        kind,
		Channel:     channel,
		StartHeight: *spec.StartHeight,
		EndHeight:   *spec.EndHeight,
		Reason:      reason,
	}, nil
}

// ParseHeight parses a non-negative 64-bit integer height. Signs, fractions,
// blanks and values above 2^64-1 are rejected.
func ParseHeight(text string) (uint64, error) {
	if text == "" {
		return 0, errors.New("height must be a non-empty unsigned 64-bit integer")
	}
	h, err := strconv.ParseUint(text, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("invalid height %q: %w", text, err)
	}
	return h, nil
}

// ValidateSeverity accepts the integer threshold range 1..5 inclusive; the
// threshold itself counts as a hit.
func ValidateSeverity(severity int) error {
	if severity < 1 || severity > 5 {
		return fmt.Errorf("minSeverity must be between 1 and 5, got %d", severity)
	}
	return nil
}

// suppressionEqual reports whether two conditions carry identical
// registration content. Revoked state is intentionally excluded: retrying
// the same document is idempotent even after the condition was revoked
// (and never re-enables it), while differing content still conflicts.
func suppressionEqual(a, b Suppression) bool {
	return a.ID == b.ID &&
		a.ChainID == b.ChainID &&
		a.Pool == b.Pool &&
		a.Kind == b.Kind &&
		a.Channel == b.Channel &&
		a.StartHeight == b.StartHeight &&
		a.EndHeight == b.EndHeight &&
		a.Reason == b.Reason
}

// matchSuppressions returns every active condition covering the event,
// sorted by ID in lexicographic order so overlapping conditions are
// reported deterministically. Revoked conditions are skipped: they no
// longer apply to conclusions processed after the revocation.
func matchSuppressions(conds []Suppression, chainID, pool, kind, channel string, height uint64) []SuppressionHit {
	hits := []SuppressionHit{}
	for _, s := range conds {
		if s.Revoked {
			continue
		}
		if s.covers(chainID, pool, kind, channel, height) {
			hits = append(hits, SuppressionHit{ID: s.ID, Reason: s.Reason})
		}
	}
	sort.Slice(hits, func(i, j int) bool { return hits[i].ID < hits[j].ID })
	return hits
}

// victimPool returns the pool of the victim swap inside the finding's raw
// evidence. The victim is the swap whose TxHash matches the finding; the
// evidence ordering and count vary by conclusion kind, so the pool is read
// off the original exchange record rather than inferred from position.
func victimPool(f ReportFinding) (string, bool) {
	for _, s := range f.Evidence {
		if s.TxHash == f.TxHash {
			return s.Pool, true
		}
	}
	return "", false
}

// sortRecords orders processing records by height, block hash, tx hash and
// kind ascending. Channel stays out of the ordering key: generation runs for
// one channel, history may span several.
func sortRecords(records []ProcessingRecord) {
	sort.Slice(records, func(i, j int) bool {
		a, b := records[i], records[j]
		if a.BlockNumber != b.BlockNumber {
			return a.BlockNumber < b.BlockNumber
		}
		if a.BlockHash != b.BlockHash {
			return a.BlockHash < b.BlockHash
		}
		if a.Finding.TxHash != b.Finding.TxHash {
			return a.Finding.TxHash < b.Finding.TxHash
		}
		return a.Finding.Kind < b.Finding.Kind
	})
}

// alertRecord mirrors one archived record the way alert generation reads
// and writes it: every business field is decoded normally, but the embedded
// rule-version declaration is kept as its raw stored document — the same
// shape a report query keeps it in. The decoded struct cannot tell a
// missing field, an explicit null or a wrong-typed value from a real one,
// so decoding the version into the struct would process a decayed report
// under silently zeroed parameters (enabled false, severity 0, a zero
// displacement multiplier) or explain a null declaration as the built-in
// rules. A wholly absent "version" key is the only legacy shape; anything
// actually saved is kept byte for byte and re-validated before the report's
// conclusions are processed, and written back unchanged.
type alertRecord struct {
	ChainID     string          `json:"chainId"`
	BlockHash   string          `json:"blockHash"`
	BlockNumber int64           `json:"blockNumber"`
	Swaps       []Swap          `json:"swaps"`
	Findings    []ReportFinding `json:"findings"`
	Version     json.RawMessage `json:"version,omitempty"`
}

// alertArchiveDoc mirrors the archive file the way alert generation reads
// and writes it: records keep their embedded version declarations as raw
// stored documents, and registered versions are kept raw too — generation
// never consults the registry, so a corrupt registered version is that
// version's damage, not whole-archive corruption, and is written back byte
// for byte. Suppressions, processing records and reviews are decoded fully.
type alertArchiveDoc struct {
	Records        []alertRecord      `json:"records"`
	Versions       []json.RawMessage  `json:"versions,omitempty"`
	EnabledVersion string             `json:"enabledVersion,omitempty"`
	Suppressions   []Suppression      `json:"suppressions,omitempty"`
	AlertRecords   []ProcessingRecord `json:"alerts,omitempty"`
	Reviews        []ReviewObject     `json:"reviews,omitempty"`
}

// GenerateAlerts turns archived conclusions in the inclusive range
// [startHeight, endHeight] on chainID for channel into new processing
// records. Detection is not re-run: the archived finding, evidence and rule
// version are reused. A finding at least minSeverity is processed; findings
// below the threshold leave no record, so lowering the threshold later can
// still produce them. Every already-processed identity is skipped, which
// makes repeated imports, repeated generation, wider or overlapping ranges,
// version switches and restarts idempotent. Channels are independent, and
// blocks at the same height with different hashes are handled separately.
//
// All new records of one call are committed together or not at all. The
// returned slice contains only records created by this call (alerts and
// suppressions distinguished), sorted by height, block hash, tx hash and
// kind; an empty result serializes as [].
//
// Every archived report in the range must still carry an intact version
// declaration — the same proof a report query demands, re-validated from
// the raw stored document with the parser registrations pass. A missing or
// null field or rule object, a wrong type, an out-of-range number, an
// unknown field or rule, or a field declared twice in one object makes the
// whole generation fail with ErrCorruptVersion naming the chain, the block,
// the readable saved version id and the offending rule or field — even when
// that report has no conclusions, every conclusion is below the threshold,
// or every conclusion was already processed. Only an old-format record with
// no "version" key at all keeps the built-in interpretation; an explicit
// null, an empty object or a partial declaration is corruption, and an id
// of "builtin" is validated like any other. A legal declaration is used
// exactly as saved: parameters are never completed from the enabled or a
// registered version, and the id need not still be registered. A failed
// generation changes nothing: reports, existing processing records and
// suppressions are all left untouched.
func GenerateAlerts(dir, chainID, channel string, startHeight, endHeight uint64, minSeverity int) ([]ProcessingRecord, error) {
	if strings.TrimSpace(chainID) == "" {
		return nil, errors.New("chainId must be a non-empty string")
	}
	if strings.TrimSpace(channel) == "" {
		return nil, errors.New("channel must be a non-empty name")
	}
	if err := ValidateSeverity(minSeverity); err != nil {
		return nil, err
	}
	if startHeight > endHeight {
		return nil, fmt.Errorf("startHeight %d must not exceed endHeight %d", startHeight, endHeight)
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, err
	}
	lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
	if err != nil {
		return nil, err
	}
	defer lock.Close()

	// Decode with each record's embedded version declaration kept as its
	// raw stored document, the same shape a report query uses: a decayed
	// declaration is that report's corruption, judged on its own below,
	// rather than whole-archive corruption or silently zeroed parameters.
	raw, err := readArchiveBytes(dir)
	if err != nil {
		return nil, err
	}
	data := alertArchiveDoc{Records: []alertRecord{}}
	if raw != nil {
		if err := json.Unmarshal(raw, &data); err != nil {
			return nil, fmt.Errorf("archive is corrupted: %w", err)
		}
	}
	processed := make(map[alertKey]struct{}, len(data.AlertRecords))
	for _, r := range data.AlertRecords {
		processed[r.identity()] = struct{}{}
	}

	created := []ProcessingRecord{}
	for _, rec := range data.Records {
		if rec.ChainID != chainID {
			continue
		}
		height := uint64(rec.BlockNumber)
		if height < startHeight || height > endHeight {
			continue
		}
		// Prove the saved declaration before any of the report's
		// conclusions is processed — and even when none would be. A wholly
		// absent version key is the only legacy shape and means builtin;
		// every declaration that was actually written must stand on its
		// own, and a corrupt one fails the whole generation before
		// anything is written.
		version, err := archivedReportVersion(rec.Version)
		if err != nil {
			return nil, corruptReportError(chainID, rec.BlockHash, rec.Version, err)
		}
		for _, f := range rec.Findings {
			if f.Severity < minSeverity {
				// Below the threshold: no record is written, so the event
				// stays eligible after a later threshold reduction.
				continue
			}
			key := alertKey{
				chainID:   rec.ChainID,
				blockHash: rec.BlockHash,
				txHash:    f.TxHash,
				kind:      f.Kind,
				channel:   channel,
			}
			if _, ok := processed[key]; ok {
				continue
			}
			pool, ok := victimPool(f)
			if !ok {
				return nil, fmt.Errorf("archive is corrupted: archived finding for block %s/%s tx %s has no victim swap in its evidence",
					rec.ChainID, rec.BlockHash, f.TxHash)
			}
			hits := matchSuppressions(data.Suppressions, rec.ChainID, pool, f.Kind, channel, height)
			status := AlertStatusAlert
			if len(hits) > 0 {
				status = AlertStatusSuppressed
			}
			record := ProcessingRecord{
				ChainID:      rec.ChainID,
				BlockHash:    rec.BlockHash,
				BlockNumber:  height,
				Pool:         pool,
				Channel:      channel,
				Finding:      f,
				Version:      version,
				MinSeverity:  minSeverity,
				Status:       status,
				Suppressions: hits,
			}
			created = append(created, record)
			processed[key] = struct{}{}
		}
	}
	sortRecords(created)
	if len(created) > 0 {
		data.AlertRecords = append(data.AlertRecords, created...)
		if err := writeArchiveAtomic(dir, data); err != nil {
			return nil, err
		}
	}
	return created, nil
}

// AlertHistory returns stored processing records on chainID for channel in
// the inclusive range [startHeight, endHeight]. It only reads the archive;
// suppressions registered afterwards cannot alter the stored content.
func AlertHistory(dir, chainID, channel string, startHeight, endHeight uint64) ([]ProcessingRecord, error) {
	if strings.TrimSpace(chainID) == "" {
		return nil, errors.New("chainId must be a non-empty string")
	}
	if strings.TrimSpace(channel) == "" {
		return nil, errors.New("channel must be a non-empty name")
	}
	if startHeight > endHeight {
		return nil, fmt.Errorf("startHeight %d must not exceed endHeight %d", startHeight, endHeight)
	}
	if _, serr := os.Stat(dir); serr != nil {
		if errors.Is(serr, os.ErrNotExist) {
			return []ProcessingRecord{}, nil
		}
		return nil, serr
	}
	lock, err := lockArchive(dir, syscall.LOCK_SH)
	if err != nil {
		return nil, err
	}
	defer lock.Close()

	data, err := readArchive(dir)
	if err != nil {
		return nil, err
	}
	out := []ProcessingRecord{}
	for _, r := range data.AlertRecords {
		if r.ChainID != chainID || r.Channel != channel {
			continue
		}
		if r.BlockNumber < startHeight || r.BlockNumber > endHeight {
			continue
		}
		out = append(out, r)
	}
	sortRecords(out)
	return out, nil
}

// RegisterSuppression validates raw and stores one suppression condition in
// the archive. Re-registering the same ID with identical content succeeds
// without adding anything (created is false) — this stays true after the
// condition was revoked and never re-enables it; the same ID with different
// content is rejected. New conditions only affect conclusions that have not
// been processed yet: historical alerts are never rewritten as suppressed,
// and suppressed records are not re-alerted when a condition's range ends.
// The registration document cannot set revoked state.
func RegisterSuppression(dir string, raw []byte) (s Suppression, created bool, err error) {
	s, err = ParseSuppression(raw)
	if err != nil {
		return Suppression{}, false, err
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return Suppression{}, false, err
	}
	lock, lerr := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
	if lerr != nil {
		return Suppression{}, false, lerr
	}
	defer lock.Close()

	data, err := readArchive(dir)
	if err != nil {
		return Suppression{}, false, err
	}
	for _, existing := range data.Suppressions {
		if existing.ID == s.ID {
			if suppressionEqual(existing, s) {
				return existing, false, nil
			}
			return Suppression{}, false, fmt.Errorf("%w: %s", ErrSuppressionConflict, s.ID)
		}
	}
	data.Suppressions = append(data.Suppressions, s)
	if err := writeArchiveAtomic(dir, data); err != nil {
		return Suppression{}, false, err
	}
	return s, true, nil
}

// RevokeSuppression withdraws the condition with the given exact ID. The
// first successful revocation returns changed=true and the full condition
// with Revoked set; revoking the same ID again succeeds with changed=false.
// A blank ID is rejected, and an ID that was never registered — including
// any ID in an empty archive — returns ErrUnknownSuppression. The revoked
// condition is retained (still listed) but stops matching conclusions
// processed from now on; it cannot be revived, a fresh ID is required to
// suppress again.
//
// The revocation is committed atomically under the archive lock: a busy
// archive, a corrupted one or a failed save leaves every condition, report
// and processing record untouched. One generation run always sees either
// the pre- or the post-revocation condition set in full.
func RevokeSuppression(dir, id string) (s Suppression, changed bool, err error) {
	if strings.TrimSpace(id) == "" {
		return Suppression{}, false, errors.New("suppression id must be a non-empty string")
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return Suppression{}, false, err
	}
	lock, lerr := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
	if lerr != nil {
		return Suppression{}, false, lerr
	}
	defer lock.Close()

	data, err := readArchive(dir)
	if err != nil {
		return Suppression{}, false, err
	}
	for i := range data.Suppressions {
		if data.Suppressions[i].ID != id {
			continue
		}
		if data.Suppressions[i].Revoked {
			return data.Suppressions[i], false, nil
		}
		data.Suppressions[i].Revoked = true
		if err := writeArchiveAtomic(dir, data); err != nil {
			return Suppression{}, false, err
		}
		return data.Suppressions[i], true, nil
	}
	return Suppression{}, false, fmt.Errorf("%w: %s", ErrUnknownSuppression, id)
}

// ListSuppressions returns every suppression condition stored in the
// archive, ordered by ID. A read on an absent archive returns an empty list.
func ListSuppressions(dir string) ([]Suppression, error) {
	if _, serr := os.Stat(dir); serr != nil {
		if errors.Is(serr, os.ErrNotExist) {
			return []Suppression{}, nil
		}
		return nil, serr
	}
	lock, err := lockArchive(dir, syscall.LOCK_SH)
	if err != nil {
		return nil, err
	}
	defer lock.Close()

	data, err := readArchive(dir)
	if err != nil {
		return nil, err
	}
	out := append([]Suppression(nil), data.Suppressions...)
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	if out == nil {
		out = []Suppression{}
	}
	return out, nil
}

